    c.strokeStyle = 'rgba(52,26,10,.07)'; c.lineWidth = px * 0.9; c.beginPath(); c.ellipse(rx + mr * 0.22, ry + mr * 0.04, mr * 0.96, mr * 0.28, 0, 2.2, TAU + 1.2); c.stroke();
