      for (const mx of [w * 0.33, w * 0.67]) { const bw = F * 1.7; g.fillStyle = lin(g, mx - bw, 0, mx + bw, 0, [[0, 'rgba(0,0,0,0)'], [0.5, 'rgba(0,0,0,.95)'], [1, 'rgba(0,0,0,0)']]); g.fillRect(mx - bw, y0, bw * 2, sh); }
      g.restore();
