      { const p0 = at(bx, by, 0.8 * s), p1 = at(bx, by, 0.98 * s); g.fillStyle = 'rgba(0,0,0,.88)'; g.beginPath(); g.moveTo(p0[0] - s * 0.27, p0[1]); g.lineTo(p0[0] + s * 0.27, p0[1]); g.lineTo(p1[0], p1[1]); g.closePath(); g.fill(); } // the roof
      { const p = at(bx, by, 1.07 * s); g.strokeStyle = 'rgba(0,0,0,.7)'; g.lineWidth = s * 0.02; g.beginPath(); g.ellipse(p[0], p[1], s * 0.05, s * 0.05 * len, 0, 0, TAU); g.stroke(); }
