      { const p = at(mug.x + mr * 1.15, mug.y, mh * 0.52); g.strokeStyle = 'rgba(0,0,0,.8)'; g.lineWidth = mh * 0.11; g.beginPath(); g.ellipse(p[0], p[1], mh * 0.17, mh * 0.24 * len, 0, 0, TAU); g.stroke(); }
