    for (let i = 0; i < n; i++) { const j = Math.ceil(i / 2), side = i % 2 ? 1 : -1; birds.push({ dx: -j * u * 0.032 * (0.8 + R() * 0.4), dy: side * j * u * 0.017 * (0.7 + R() * 0.6), ph: R() * TAU, f: 2.2 + R() * 1.1, s: 0.85 + R() * 0.3 }); }
