  const forestDawn = (T) => wxSm(4.6, 5.9, T) * (1 - wxSm(7.9, 10.3, T)); // mist in the trees, lifting by mid-morning
  const forestFlyHour = (T) => { const x = wxHour(T - 19.1); return wxSm(0, 0.9, x) * (1 - wxSm(4.3, 6.2, x)); }; // fireflies from dusk to about midnight
  const forestBirdHour = (T) => wxSm(5.3, 5.9, T) * (1 - wxSm(7.8, 8.6, T)) + 0.55 * wxSm(18.2, 18.7, T) * (1 - wxSm(19.6, 20.1, T));
  const forestTeaHour = (T) => { const e = wxHour(T - 20.4); return wxSm(5.9, 6.6, T) * (1 - wxSm(10.6, 11.6, T)) + wxSm(0, 0.6, e) * (1 - wxSm(3.1, 3.7, e)); };
  /* motion:forest:end */

  /* motion:washitsu:start */
  // ---- Chambre japonaise ----
  // A tatami room seen from the floor, at the eye height of someone sitting on it: the tokonoma on the left, closed shoji in
  // the middle (under the reading column), and on the right the shoji slid open onto the engawa and a small garden: raked
  // gravel, a stone lantern, a shishi-odoshi, a maple, a pruned pine, a bamboo fence, and far off the hills and a pagoda.
  // The sun and the moon cross the strip of sky in the opening (fx), east on the left.
  // draw() paints the room in daylight colours, keeps a copy, darkens the room to the sky's light and adds the copy back
  // under a light map (the andon's pool, the sun or the moon thrown on the tatami through the opening and the shoji), so
  // lamplight shows the colours of things instead of laying a haze on them. The garden's colours are worked out per sky.
  const washitsuSm = (a, b, x) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
  const washitsuH = (n) => { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };
