    { const ha = [G.px(X - hw, d + 0.135), G.py(d + 0.135, Hs.t1)], hb = [G.px(X + hw, d + 0.135), G.py(d + 0.135, Hs.t1)], hy = G.py(d + 0.135, Hs.t1 + 0.16), e = Math.max(0.8, s * 0.009);
      A.silH = new Path2D(); A.silH.moveTo(ha[0] - e, ha[1] + e); A.silH.bezierCurveTo(ha[0] - e, hy - e, hb[0] + e, hy - e, hb[0] + e, hb[1] + e); A.silH.lineTo(hb[0] - e, hb[1] + e); A.silH.bezierCurveTo(hb[0] - e, hy + e, ha[0] + e, hy + e, ha[0] + e, ha[1] + e); A.silH.closePath(); }
