    c.fillStyle = rad(c, gx, fl, s * 0.14, [[0, `rgba(255,250,232,${0.9 * k})`], [0.4, `rgba(255,232,180,${0.4 * k})`], [1, 'rgba(255,220,160,0)']]); c.fillRect(up[0], up[1], up[2] - up[0], up[3] - up[1]);
