    c.fillStyle = 'rgba(80,56,32,.25)'; c.fillRect(0, yC, w, Math.max(0.8, h * 0.004));
    c.fillStyle = '#7e5e40'; c.fillRect(r0, ry0 - h * 0.004, r1 - r0, ry1 - ry0 + h * 0.008);
    c.fillStyle = '#d8ccb2'; const sl = Math.max(1, M * 0.03), gp = Math.max(1, M * 0.05);
    for (let x = r0 + sl; x + gp < r1 - sl * 0.5; x += sl + gp) { c.fillRect(x, ry0, gp, ry1 - ry0); ranma.rect(x, ry0, gp, ry1 - ry0); }
