    c.save(); c.beginPath(); c.rect(0, yR, w, yK - yR); c.clip(); kitTex(c, 'wood', 0, yR, w, yK - yR, 0.22, Math.max(0.3, kS * 0.8)); c.restore();
    c.fillStyle = 'rgba(255,236,200,.35)'; c.fillRect(0, yR, w, Math.max(0.6, h * 0.0015)); c.fillStyle = 'rgba(40,24,10,.45)'; c.fillRect(0, yK - Math.max(0.8, h * 0.002), w, Math.max(0.8, h * 0.002));
