    const nT = h * 0.17, nB = yF - M * 0.1, kk = 0.87, bx = (x) => G.vx + (x - G.vx) * kk, by = (y) => G.yH + (y - G.yH) * kk;
    c.save(); c.beginPath(); c.rect(0, nT, xT, yF - nT); c.clip();
    c.fillStyle = lin(c, 0, by(nT), 0, by(nB), [[0, '#c3aa82'], [1, '#cdb48c']]); c.fillRect(0, nT, xT, yF - nT);
    c.fillStyle = '#d6bf98'; c.beginPath(); washitsuPoly(c, [[0, nT], [bx(0), by(nT)], [bx(0), by(nB)], [0, nB]]); c.fill();
    kitTex(c, 'stone', 0, nT, xT, yF - nT, 0.12, Math.max(0.35, kS * 0.6));
    c.fillStyle = '#a28a65'; c.beginPath(); washitsuPoly(c, [[0, nT], [xT + 20, nT], [bx(xT + 20), by(nT)], [bx(0), by(nT)]]); c.fill();
    c.fillStyle = lin(c, 0, by(nB), 0, nB, [[0, '#7a5a3a'], [1, '#94704a']]); c.beginPath(); washitsuPoly(c, [[0, nB], [xT + 20, nB], [bx(xT + 20), by(nB)], [bx(0), by(nB)]]); c.fill();
    c.save(); c.beginPath(); washitsuPoly(c, [[0, nB], [xT + 20, nB], [bx(xT + 20), by(nB)], [bx(0), by(nB)]]); c.clip(); kitTex(c, 'wood', 0, by(nB), xT + 20, nB - by(nB), 0.28, Math.max(0.3, kS * 0.9)); c.restore();
    c.fillStyle = lin(c, bx(0), 0, xT, 0, [[0, 'rgba(60,40,20,.18)'], [0.2, 'rgba(60,40,20,0)'], [0.85, 'rgba(60,40,20,0)'], [1, 'rgba(60,40,20,.16)']]); c.fillRect(0, by(nT), xT, by(nB) - by(nT));
    c.fillStyle = lin(c, 0, by(nT), 0, by(nT) + h * 0.05, [[0, 'rgba(50,34,18,.25)'], [1, 'rgba(50,34,18,0)']]); c.fillRect(0, by(nT), xT, h * 0.05);
    const scX = (bx(0) + xT) / 2 - G.M * 0.04, scW = M * 0.3 * kk, scY = by(nT) + h * 0.02, scH = M * 1.05 * kk;
    washitsuScroll(c, scX, scY, scW, scH);
