    c.fillStyle = lin(c, 0, nB, 0, yF, [[0, '#3a302a'], [0.2, '#1e1814'], [1, '#14100d']]); c.fillRect(0, nB, xT, yF - nB);
    c.fillStyle = 'rgba(255,240,215,.3)'; c.fillRect(0, nB, xT, Math.max(0.6, h * 0.0015));
