    // The shoji: three panels, 3 x 7 panes of paper on a lattice, a wooden panel at the foot.
    const n = 3, pw = (xP - xS) / n, fw = Math.max(1, M * 0.032), kw = Math.max(0.6, M * 0.011), kh = M * 0.27;
    for (let i = 0; i < n; i++) {
      const x0 = xS + i * pw, ax = x0 + fw, ay = yK + fw, aw = pw - 2 * fw, ab = yS - kh, ah = ab - fw - ay;
      c.fillStyle = '#b38e64'; c.fillRect(x0, yK, pw, yS - yK);
      c.fillStyle = lin(c, 0, ab, 0, yS, [[0, '#a17d56'], [1, '#8a6846']]); c.fillRect(ax, ab, aw, yS - ab - fw * 0.5);
      c.fillStyle = 'rgba(255,235,200,.2)'; c.fillRect(ax, ab, aw, Math.max(0.6, kw * 0.6));
      for (let r = 0; r < 7; r++) for (let q = 0; q < 3; q++) {
        const cx = ax + q * (aw + kw) / 3, cy = ay + r * (ah + kw) / 7, cw = (aw + kw) / 3 - kw, ch = (ah + kw) / 7 - kw, v = (washitsuH(i * 31 + r * 7 + q) - 0.5) * 8;
        c.fillStyle = `rgb(${238 + v | 0},${232 + v | 0},${216 + v * 1.4 | 0})`; c.fillRect(cx, cy, cw, ch); paper.rect(cx, cy, cw, ch);
      }
      c.fillStyle = 'rgba(60,40,20,.4)'; c.fillRect(x0 + pw - Math.max(0.6, fw * 0.2), yK, Math.max(0.6, fw * 0.2), yS - yK);
    }
    out.shoji = { x0: xS, x1: xP, h0: 0.28 + 0.03, h1: 1.8 - 0.03, cols: 9, rows: 7 };
    // The post by the opening, lit on the side that faces the garden.
    c.fillStyle = lin(c, xP, 0, xo, 0, [[0, '#7e5e3e'], [0.6, '#977350'], [0.75, '#b58f66'], [1, '#c09a70']]); c.fillRect(xP, yC, G.pw, yF - yC);
