    for (let X = -0.45 - 0.9 * Math.ceil(XM / 0.9); X < XM; X += 0.9) R2.push(X);
    const tone = (i, row) => { const q = washitsuH(i * 7.3 + row * 19.1 + 3), b = row ? [197, 179, 125] : [205, 190, 138]; return washitsuCss(washitsuMix(b, q < 0.5 ? [186, 182, 122] : [212, 184, 124], Math.abs(q - 0.5) * 0.8)); };
    R1.forEach((X, i) => { c.fillStyle = tone(i, 0); c.beginPath(); quad(X, X + 1.8, 3.1, 4); c.fill(); });
    R2.forEach((X, i) => { c.fillStyle = tone(i, 1); c.beginPath(); quad(X, X + 0.9, dB, 3.1); c.fill(); });
    kitTex(c, 'paper', 0, yF, w, h - yF, 0.22, Math.max(1, kS * 3));
