  const NOOK_SEAT = { sun: ['255,248,226', 0.2], clouds: ['240,246,255', 0.15], golden: ['255,205,130', 0.2], sunset: ['255,150,100', 0.14], night: ['170,190,255', 0.1], rain: ['120,150,190', 0.09], storm: ['120,150,190', 0.05] };
