        gain: 1.3, ramp: 0.55, warm: 'rgba(255,205,150,.14)', veil: 'rgba(236,240,246,.04)', vig: 0.36, rim: ['240,248,255', 0.12, 0], motes: 14, curt: ['240,246,255', 0.08],
