        gain: 1.25, ramp: 0.5, warm: 'rgba(255,150,60,.24)', veil: 'rgba(255,170,90,.06)', vig: 0.42, rim: ['255,196,110', 0.12, 0.3], motes: 16, curt: ['255,200,110', 0.16],
