    const key = kitMix(kitRGB(Wd.tint || '250,244,232'), D.e > 0 ? kitRGB(wxSunRGB(D.e)) : [178, 196, 255], 0.4);
    const R = kitRig({ dir: side, front: 0.05, rgb: key, k: 0.3 + 0.75 * day, amb: kitMix(kitRGB(Wd.shade || '#334455'), [252, 248, 242], 0.45 + 0.35 * day), ka: 0.68 + 0.32 * day, bounce: '170,118,78', kb: 0.1 + 0.15 * day });
