        c.strokeStyle = lin(c, tx, ty, mx, my, [[0, 'rgba(28,16,8,.2)'], [1, 'rgba(28,16,8,0)']]); c.lineWidth = ch * 0.05; c.beginPath(); c.moveTo(tx, ty); c.quadraticCurveTo((tx + mx) / 2 + (my - ty) * 0.12, (ty + my) / 2 - (mx - tx) * 0.12, mx, my); c.stroke();
