    c.fillStyle = nookCyl(c, x - fr, x + fr, wood, R, 0.1, 9); c.fill();
    ellipse(c, x, foot - fh, fr, fe, lin(c, x - fr, 0, x + fr, 0, [[0, nookCss(wood, R, -0.4, 0.3, -1)], [1, nookCss(wood, R, 0.4, 0.3, -1)]]));
    const cw = s * 0.03;
    c.fillStyle = nookCyl(c, x - cw, x + cw, wood, R); c.fillRect(x - cw, top + th, cw * 2, foot - fh - top - th);
    for (const [ry0, rw, rh] of [[top + th + s * 0.03, cw * 1.45, s * 0.03], [foot - fh - s * 0.07, cw * 1.6, s * 0.035], [foot - fh - s * 0.025, cw * 1.25, s * 0.025]]) {
      c.fillStyle = nookCyl(c, x - rw, x + rw, wood, R); rrect(c, x - rw, ry0, rw * 2, rh, rh * 0.45); c.fill();
      c.fillStyle = nookCss(wood, R, 0.3, 0.5, -0.8, 0.5); c.fillRect(x - rw * 0.8, ry0, rw * 1.6, Math.max(0.6, rh * 0.12));
    }
    c.fillStyle = lin(c, 0, top + th, 0, top + th + s * 0.14, [[0, 'rgba(16,8,3,.6)'], [1, 'rgba(16,8,3,0)']]); c.fillRect(x - cw * 1.7, top + th, cw * 3.4, s * 0.14);
