    c.save(); c.filter = `blur(${Math.max(1, bw * 0.011).toFixed(1)}px)`; c.fillStyle = 'rgba(10,5,2,.42)'; c.translate(bw * 0.003, bh * 0.008); shape(c); c.fill(); c.restore();
    const bx = [x - edge, y0 - 2, bw + edge * 2, yb - y0 + bh * 0.12];
    c.save(); shape(c); c.clip();
    c.fillStyle = nookCss(wool, R, 0, 1, 0); c.fillRect(...bx);
