    fg.globalCompositeOperation = 'destination-in'; fg.fillStyle = lin(fg, 0, y1, 0, yb, [[0, 'rgba(0,0,0,.3)'], [0.5, 'rgba(0,0,0,.76)'], [1, 'rgba(0,0,0,1)']]); fg.fillRect(x - edge, y1, bw + edge * 2, yb - y1 + bh * 0.1);
