    c.fillStyle = lin(c, x + bw * 0.94, 0, x + bw + edge * 0.3, 0, [[0, 'rgba(28,14,6,0)'], [1, 'rgba(28,14,6,.34)']]); c.fillRect(x + bw * 0.94, y0, bw * 0.06 + edge, bx[3]);
