      c.fillStyle = nookCyl(c, x, x + bw, cloth, RL, 0, 7); c.fillRect(x, top, bw, bh);
      c.fillStyle = 'rgba(0,0,0,.28)'; c.fillRect(x, top, bw, Math.max(0.6, bh * 0.014));
      if (kind < 0.42) { c.fillStyle = nookCss({ base: '#c49a4c', gloss: 0.5 }, RL, 0, 1, 0, 0.6); for (const f of [0.88, 0.85, 0.13]) c.fillRect(x + bw * 0.12, base - bh * f, bw * 0.76, Math.max(0.6, bh * 0.012)); }
      else if (kind < 0.62) { for (const f of [0.78, 0.55, 0.32]) { c.fillStyle = 'rgba(0,0,0,.25)'; c.fillRect(x, base - bh * f, bw, Math.max(0.6, bh * 0.016)); c.fillStyle = 'rgba(255,236,206,.12)'; c.fillRect(x, base - bh * f - Math.max(0.6, bh * 0.012), bw, Math.max(0.6, bh * 0.012)); } }
      else if (kind < 0.8) { c.fillStyle = nookCss({ base: '#d6c7a6' }, RL, 0, 1, 0, 0.72); c.fillRect(x + bw * 0.18, base - bh * 0.72, bw * 0.64, bh * 0.13); }
      x += bw + Math.max(0.6, unit * 0.05);
