      nookBookRow(c, x + side * 1.1, x + w - side * 1.1, base, rh * 0.8, unit, R, RL);
      c.fillStyle = lin(c, 0, ceil, 0, ceil + rh * 0.5, [[0, 'rgba(6,3,1,.6)'], [1, 'rgba(6,3,1,0)']]); c.fillRect(x + side, ceil, w - 2 * side, rh * 0.5);
      c.fillStyle = nookCss(wood, RL, 0, 1, 0.1); c.fillRect(x, base, w, side * 0.5);
      c.fillStyle = nookCss(wood, RL, 0, 0.4, -1, 0.9); c.fillRect(x, base, w, Math.max(1, side * 0.1));
