    c.fillStyle = lin(c, 0, y + hh, 0, y + h, [[0, kitCss(nookSc(nookLit(wood, RL, 0, 0.9, 0.2), 0.55))], [1, kitCss(nookSc(nookLit(wood, RL, 0, 0.9, 0.2), 0.4))]]); c.fillRect(x, y + hh, w, pl);
    c.fillStyle = lin(c, 0, y + hh, 0, y + hh + pl * 0.55, [[0, 'rgba(4,2,1,.7)'], [1, 'rgba(4,2,1,0)']]); c.fillRect(x, y + hh, w, pl * 0.55);
    c.fillStyle = nookCss(wood, RL, 0, 0.4, -1, 0.5); c.fillRect(x, y + hh, w, Math.max(1, side * 0.1));
