    c.save(); c.beginPath(); c.rect(x, y, side, hh); c.rect(x + w - side, y, side, hh); c.clip(); kitTex(c, 'wood', x, y, w, h, 0.3, 0.6, 90); c.restore();
    c.save(); c.beginPath(); for (const b of boards) c.rect(...b); c.rect(x, y, w, side); c.rect(x, y + hh, w, pl); c.clip(); kitTex(c, 'wood', x, y, w, h, 0.3, 0.6); c.restore();
