    const midY = (x) => hz - h * (0.004 + 0.013 * n3(x / w, 8.1, 19.3, 47, 4.4)) - h * 0.005 * n3(x / u, 97, 211, 389, 0.7);
    const xl = w * (port ? 0.2 : 0.17), xr = w * (port ? 0.74 : 0.775);
    const leftY = (x) => (x >= xl ? hz + 3 : hz - h * 0.11 * Math.pow(1 - Math.max(0, x) / xl, 1.2) - h * 0.01 * n3(x / w, 37, 71, 150, 0.4) * (1 - Math.max(0, x) / xl) - h * 0.003);
    const rightY = (x) => (x <= xr ? hz + 3 : hz - h * 0.2 * Math.pow((Math.min(x, w) - xr) / (w - xr), 1.45) - h * 0.012 * n3(x / w, 33, 63, 140, 2.2) * Math.min(1, (x - xr) / (w * 0.05)) - h * 0.003);
