    const top = (x) => Math.min(fujiY(x), farY(x), midY(x), x < xl ? leftY(x) - h * 0.045 : hz, x > xr ? rightY(x) - h * 0.045 : hz, Math.abs(x - tor.x) < TH * 0.6 ? tor.base - TH : hz);
