    for (const [i, T] of toro.entries()) lamps.push({ id: T.id, kind: 'toro', x: T.x, y: T.base - T.s * 0.578, s: T.s * 0.3, wy: bank.bot + 1, rl: sh * 0.08, ph0: 3 + i * 1.3 });
    Object.assign(G, { sh, bank, pier, lamps, toro, boat: { y: Math.round(h * 0.745), s: u * 0.075 } });
