    // the plinth and its cushion
    add(fujiHex(g, x, base - s * 0.07, s * 0.44, base, s * 0.47, grD, R, G, { ao: 0.7 }));
    const cu = fujiHex(g, x, base - s * 0.1, s * 0.3, base - s * 0.07, s * 0.37, gr, R, G); add(cu);
    // the post, with its ring, in the platform's shadow at the top
    const p0 = base - s * 0.405, p1 = base - s * 0.1, pw = s * 0.054, post = new Path2D();
    post.moveTo(x - pw * 0.95, p0); post.lineTo(x + pw * 0.95, p0); post.lineTo(x + pw * 1.05, p1); post.lineTo(x - pw * 1.05, p1); post.closePath();
    g.fillStyle = kitCylGrad(g, x - pw, x + pw, gr, R); g.fill(post); add(post);
    const ring = new Path2D(); ring.rect(x - pw * 1.25, base - s * 0.265, pw * 2.5, s * 0.026);
    g.fillStyle = kitCylGrad(g, x - pw * 1.25, x + pw * 1.25, gr, R); g.fill(ring); add(ring);
    g.fillStyle = kitCss(fujiTop(gr, R), 0.8); g.fillRect(x - pw * 1.25, base - s * 0.265, pw * 2.5, Math.max(0.5, s * 0.005));
    g.fillStyle = 'rgba(0,0,0,.22)'; g.fillRect(x - pw * 1.05, base - s * 0.239, pw * 2.1, Math.max(0.6, s * 0.01));
    g.fillStyle = lin(g, 0, p0, 0, p0 + s * 0.07, [[0, 'rgba(10,8,12,.42)'], [1, 'rgba(10,8,12,0)']]); g.fillRect(x - pw * 1.1, p0, pw * 2.2, s * 0.07);
    // the platform: a flaring lotus, then its slab
    const fl = fujiHex(g, x, base - s * 0.462, s * 0.36, base - s * 0.405, s * 0.13, gr, R, G, { ao: 0.62, top: false }); add(fl);
    g.save(); g.clip(fl); g.lineWidth = Math.max(0.5, s * 0.006);
    for (let i = -3; i <= 3; i++) { const px = x + i * s * 0.052, py = base - s * 0.44; g.strokeStyle = 'rgba(0,0,0,.2)'; g.beginPath(); g.moveTo(px - s * 0.026, base - s * 0.462); g.quadraticCurveTo(px - s * 0.024, py + s * 0.012, px, py + s * 0.02); g.quadraticCurveTo(px + s * 0.024, py + s * 0.012, px + s * 0.026, base - s * 0.462); g.stroke(); g.strokeStyle = kitCss(fujiTop(gr, R), 0.35); g.beginPath(); g.moveTo(px - s * 0.018, base - s * 0.459); g.quadraticCurveTo(px, py + s * 0.004, px + s * 0.018, base - s * 0.459); g.stroke(); }
    g.restore();
    const slab = fujiHex(g, x, base - s * 0.49, s * 0.39, base - s * 0.462, s * 0.39, gr, R, G); add(slab);
    // the fire box and its window; no moon or sun cut in its sides (they read as stains beside the window, lit or not)
