    const wx0 = x - bw * 0.15, wx1 = x + bw * 0.15, wy0 = b0 + s * 0.022, wy1 = b1 - s * 0.018, hole = new Path2D();
    hole.rect(wx0, wy0, wx1 - wx0, wy1 - wy0);
