    const yb = base - s * 0.665, rw = s * 0.76, eh = s * 0.034, curl = s * 0.045, yt = base - s * 0.855, ye = yb - eh, ax = s * 0.03;
    const und = new Path2D(); und.moveTo(x - rw * 0.25, yb); und.lineTo(x + rw * 0.25, yb); und.lineTo(x + rw * 0.5, yb - curl); und.lineTo(x + rw * 0.4, yb + s * 0.012); und.lineTo(x - rw * 0.4, yb + s * 0.012); und.lineTo(x - rw * 0.5, yb - curl); und.closePath();
