    const jw = new Path2D(), jy = yt - s * 0.022; jw.moveTo(x - s * 0.042, jy); jw.bezierCurveTo(x - s * 0.06, jy - s * 0.045, x - s * 0.012, jy - s * 0.07, x, jy - s * 0.1); jw.bezierCurveTo(x + s * 0.012, jy - s * 0.07, x + s * 0.06, jy - s * 0.045, x + s * 0.042, jy); jw.closePath();
