    g.fillStyle = kitCss(kitMix(fujiTop(gr, R), [214, 222, 196], 0.5), 0.4); g.beginPath();
    for (let i = 0; i < 14; i++) { const lx = x + (Rn() - 0.5) * rw * 0.8, ly = ye - Rn() * (ye - yt) * 0.8, r = s * (0.006 + Rn() * 0.01); g.moveTo(lx + r, ly); g.ellipse(lx, ly, r, r * 0.7, 0, 0, TAU); } g.fill();
