      g.save(); g.clip(eave); g.fillStyle = rad(g, lx, yb + s * 0.02, s * 0.2, [[0, `rgba(255,170,90,${(0.3 * warm).toFixed(3)})`], [1, 'rgba(255,150,80,0)']]); g.fillRect(x - rw / 2, ye - curl, rw, eh + curl); g.restore();
