    g.beginPath(); g.moveTo(x - rw, by); g.quadraticCurveTo(x, by + s * 0.035, x + rw, by); g.lineTo(x + rw, by + bh); g.quadraticCurveTo(x, by + bh + s * 0.035, x - rw, by + bh); g.closePath(); g.fill();
    if (warm <= 0) { g.fillStyle = lin(g, x - rw, 0, x + rw, 0, [[0, 'rgba(0,0,0,.3)'], [0.45, 'rgba(0,0,0,0)'], [1, 'rgba(0,0,0,.35)']]); g.fillRect(x - rw, by, rw * 2, bh + s * 0.04); }
    g.fillStyle = warm > 0 ? 'rgba(60,14,8,.6)' : 'rgba(26,18,16,.7)'; g.beginPath(); g.arc(x, by + bh * 0.55, bh * 0.28, 0, TAU); g.fill();
    // the candle seen through the paper; the soft dark at the edges where the paper is seen edgewise
    if (warm > 0) { g.globalCompositeOperation = 'lighter'; g.fillStyle = rad(g, x, y + rh * 0.42, rh * 0.32, [[0, `rgba(255,236,190,${(0.5 * warm).toFixed(3)})`], [1, 'rgba(255,200,120,0)']]); g.fillRect(x - rw, y, rw * 2, rh); g.globalCompositeOperation = 'source-over'; }
    g.fillStyle = rad(g, x, y, Math.max(rw, rh), [[0.55, 'rgba(0,0,0,0)'], [1, `rgba(${warm > 0 ? '90,30,10' : '20,16,14'},${warm > 0 ? 0.35 : 0.22})`]]); g.fillRect(x - rw, y - rh, rw * 2, rh * 2);
    g.restore();
