    for (k = 1; k <= n; k++) { var t2 = k / n, x2 = C[0] + (B[0] - C[0]) * t2, z2 = C[1] + (B[1] - C[1]) * t2; pts.push(plageThingP(G, x2, lift * (1 - t2) + 0.004, z2)); }
