    var F = plageThingFlapPts(G, T, 0.022);
    var blue = plageThingMix([74, 112, 168], [243, 234, 214], 0.45), cream = [236, 228, 210];
    var lt = plageThingLight(L, 0.15 * (L.dir || 0), 1, -0.25);
