    c.strokeStyle = plageThingShadowMul(L, 0.9) === 'rgb(255,255,255)' ? 'rgba(120,120,140,0.25)' : 'rgba(110,105,120,' + (0.18 + 0.2 * L.k) + ')';
    c.lineWidth = Math.max(2, u * 0.006); c.lineJoin = 'round';
    c.beginPath(); for (var i = 1; i < F.pts.length; i++) { if (i === 1) c.moveTo(F.pts[i][0], F.pts[i][1] + 2); else c.lineTo(F.pts[i][0], F.pts[i][1] + 2); }
    c.stroke();
