    var vl = Math.hypot(V[0], V[1]) || 1, px = -V[1] / vl, pz = V[0] / vl, tx = X + V[0] * Ht, tz = Math.max(0.35, Z + V[1] * Ht);
    var a = plageThingP(G, X + px * W, 0, Z + pz * W), b = plageThingP(G, X - px * W, 0, Z - pz * W), c2 = plageThingP(G, tx - px * W * 0.8, 0, tz - pz * W * 0.8), d = plageThingP(G, tx + px * W * 0.8, 0, tz + pz * W * 0.8);
