    c.beginPath();
    c.ellipse(x, y, W * 0.5, W * 0.5 * e, 0, 0, Math.PI);
    c.lineTo(x - W * 0.5, yB + W * 0.5 * e * 0.2);
    c.ellipse(x, yB, W * 0.47, W * 0.47 * e, 0, Math.PI, 0, true);
    c.closePath(); c.fill();
    c.fillStyle = sh(metal, 0, 1, 0, 1.05);
    c.beginPath(); c.ellipse(x, yB, W * 0.47, W * 0.47 * e, 0, 0, Math.PI * 2); c.fill();
    // verre : intérieur (fond)
