    c.save();
    c.beginPath();
    c.ellipse(x, yB, Wg * 0.5, Wg * 0.5 * e, 0, 0, Math.PI);
    c.lineTo(x - Wg * 0.5, yG);
    c.ellipse(x, yG, Wg * 0.5, Wg * 0.5 * e, 0, Math.PI, 0, false);
    c.closePath();
    c.clip();
