    var hx = x + (sd >= 0 ? 1 : -1) * Wg * 0.28;
    var rgl = c.createLinearGradient(0, yG, 0, yB);
    var ra = (0.25 + 0.35 * L.k) * (1 - 0.6 * glow) + 0.08;
    rgl.addColorStop(0, plageThingRgb(L.sun, [1, 1, 1], 1, 0)); rgl.addColorStop(0.3, plageThingRgb(plageThingMix(L.sun, L.amb, 1 - day * 0.5), [1, 1, 1], 1, ra)); rgl.addColorStop(1, plageThingRgb(L.sun, [1, 1, 1], 1, ra * 0.3));
