    c.fillStyle = sh(metal, 0, 0.1, -1, 1);
    c.fillRect(x - rib * 0.45, yG + Wg * 0.5 * e, rib * 0.9, gh);
    // toit : bague + cône + bouton
    c.fillStyle = cylGrad(x, W * 0.5, metal, 1.05);
    c.beginPath(); c.ellipse(x, yG + s * 0.015, W * 0.5, W * 0.5 * e, 0, 0, Math.PI); c.lineTo(x - W * 0.5, yG - s * 0.02);
    c.ellipse(x, yG - s * 0.02, W * 0.5, W * 0.5 * e, 0, Math.PI, 0, false); c.closePath(); c.fill();
