    c.lineTo(x + W * 0.07, yR);
    c.quadraticCurveTo(x + W * 0.2, yR + rfh * 0.25, x + W * 0.5, yG - s * 0.02);
    c.ellipse(x, yG - s * 0.02, W * 0.5, W * 0.5 * e, 0, 0, Math.PI, false);
    c.closePath();
