      c.fillStyle = lin(c, xi0, 0, xi0 + unit * 2.2, 0, [[0, 'rgba(8,5,3,.42)'], [1, 'rgba(8,5,3,0)']]); c.fillRect(xi0, ctop, unit * 2.2, base - ctop);
      const xr = xi1 - (xi1 - Z.vx) * tk;
      c.fillStyle = lin(c, xr, 0, xr - unit * 2.2, 0, [[0, 'rgba(8,5,3,.4)'], [1, 'rgba(8,5,3,0)']]); c.fillRect(xr - unit * 2.2, ctop, unit * 2.2, base - ctop);
