  /* ---------- paris (Toits de Paris) ---------- */
  const parisSm = (a, b, x) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
  const parisCl = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
