    const potBase = [198, 104, 68];
    const potLit = parisLit(rig, potBase, 0.72, 0.32);
    const potMid = parisLit(rig, [164, 82, 54], 0.05, 0.45);
    const potShd = parisLit(rig, [104, 48, 34], -0.68, 0.62);
    const potRim = parisLit(rig, [226, 134, 92], 0.84, 0.28);

