          const d = u * 0.08, pts = flip ? [[l, ctop - 2], [r, ctop - 2], [r, sy + d], [x0, sy + d], [x0, sy], [l, sy]] : [[l, ctop - 2], [r, ctop - 2], [r, sy], [x0, sy], [x0, sy + d], [l, sy + d]];
