      integrate: 'air',
      precip: { type: 'rain', def: 0, byWeather: { sun: 0, clouds: 0, golden: 0, sunset: 0, night: 0, rain: 60, storm: 85 }, color: '215,220,245', alpha: 0.28, clip: (w, h) => ({ x: 0, y: 0, w, h }) },
      sound: 'lake',
      lights: LAKE_LIGHTS,
      grade: LAKE_GRADE,
