        const lk = 0.35 + 0.65 * D.W.lamp, litC = lit.candles ? 1 : 0, litG = lit.garland ? 1 : 0, veil = 1 - D.wet, dark = 1 - D.d, cl = 1 - 0.35 * D.c;
