          for (let i = Math.max(0, Math.floor((r.x0 - W.x) / 3)); i < env.length && W.x + i * 3 <= r.x1; i++) { const t = r.top(W.x + i * 3 - cx); if (t != null) env[i] = Math.min(env[i], t); }
