        const fw = u * 0.028, fx = (k) => W.x + W.w * k;
        const fL = cabin(fx(0.115), far.at(fx(0.115)) + W.h * 0.02, fw, 1, true, lookFar, { 1: win('farL') }, 4);
        const fR = cabin(fx(0.8), far.at(fx(0.8)) + W.h * 0.035, fw, 0, true, lookFar, { 1: win('farR', 'farM') }, 2);
        const mid = snowCrest(W.x, x1, W.y + W.h * 0.72, W.h * 0.1, [R() * 9, R() * 9, R() * 9]);
        snowFill(c, mid, x1, P.mid, sy);
